#!/usr/bin/env python3
"""Degree-four AB normalization functions are generated by coordinate quartics."""
import argparse,hashlib,json,os,subprocess,tempfile,time
from pathlib import Path
from collections import defaultdict
from ab_origin_degree_four_backend_20261101 import *

ROOT=Path(__file__).resolve().parents[1]

def main():
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--output',type=Path,required=True)
    args=parser.parse_args();started=time.time()
    h=[Counter(),Counter()];dims=[0,0];table=[]
    for j in range(5):
        cy=character(4-j,core_weights,leading);cv=character(j,vertical_weights);prod=Counter()
        assert sum(cy.values())==(5-j)**3
        for a,ca in cy.items():
            for b,cb in cv.items():prod[a[0]+b[0],a[1]+b[1]]+=ca*cb
        for a,b,m in decompose(prod):
            co=bott(a,b);table.append(dict(vertical_degree=j,Levi_weight=[a,b],multiplicity=m,cohomology=co))
            if co:
                degree,wt,dim=co;assert degree in (0,1);h[degree][wt]+=m;dims[degree]+=m*dim
    assert dims==[41621,3051]
    assert h[1]==Counter({(12,2):1,(11,1):1,(10,0):2,(12,0):1})
    # Necessary conditions on the image of a P-cyclic lowest vector.
    g0,g1,g2,u=s.symbols('g0 g1 g2 u');fiber=(*pars,g0,g1,g2)
    weights=[tuple(-a for a in wt)for wt in core_weights+vertical_weights]
    a,b,d,e=s.symbols('a b d e');chartN=s.Matrix([1,a,b])*s.Matrix([[-a*d-b*e,d,e]])
    vals=inverse*chartN.reshape(9,1);sub=dict(zip(pars,vals));chartvars=(a,b,d,e,g0,g1,g2)
    Q=Qof(N,g0*x*x+g1*x*z+g2*z*z)
    radical=s.eye(4);radical[3,2]=u;rn,rg=extract(push(radical,Q));assert rn==N
    rsub=dict(zip(fiber,(*pars,*rg)))
    T=s.Matrix([[1,u],[0,1]]);levi=s.eye(4)
    for i,ii in enumerate((0,2)):
        for j,jj in enumerate((0,2)):levi[ii,jj]=T[i,j]
    for i,ii in enumerate((1,3)):
        for j,jj in enumerate((1,3)):levi[ii,jj]=T.inv().T[i,j]
    ln,lg=extract(push(levi,Q));lsub=dict(zip(fiber,(*(inverse*ln.reshape(9,1)),*lg)))
    constraints=[]
    for aa,bb in h[1]:
        forms=[s.prod(fiber[i]for i in inds)for inds in combinations_with_replacement(range(11),4)
               if tuple(sum(weights[i][k]for i in inds)for k in range(2))==(-aa,-bb)]
        fp=[s.Poly(f.subs(sub,simultaneous=True),*chartvars)for f in forms]
        mons=sorted(set().union(*(set(p.monoms())for p in fp)))
        M=s.Matrix([[p.coeff_monomial(mm)for p in fp]for mm in mons]);piv=list(M.to_DM().rref()[1]);forms=[forms[i]for i in piv]
        ops=[]
        for f in forms:
            ff=[s.diff(f.subs(lsub,simultaneous=True),u).subs(u,0),
                s.diff(f.subs(rsub,simultaneous=True),u,bb+1).subs(u,0)]
            ops.append([s.Poly(z.subs(sub,simultaneous=True),*chartvars)for z in ff])
        rows=[]
        for j in range(2):
            mons=sorted(set().union(*(set(p[j].monoms())for p in ops)))
            rows.extend([[p[j].coeff_monomial(mm)for p in ops]for mm in mons])
        C=s.Matrix(rows);rank=C.to_DM().rank();bound=len(forms)-rank;expected=h[0][aa,bb]-h[1][aa,bb]
        assert bound==expected
        constraints.append(dict(partition=[aa,bb],weight_dimension=len(forms),constraint_rank=rank,
                                Hom_upper=bound,Euler_multiplicity=expected,forms=list(map(str,forms)),
                                constraint_matrix=[[str(x)for x in row]for row in C.tolist()]))
    # Weyl character only specifies desired lower-bound blocks; each minor below is checked.
    xx,yy=s.symbols('xx yy');den=s.expand(xx**2*yy**2*((xx**2-xx**-2)*(yy-yy**-1)-(yy**2-yy**-2)*(xx-xx**-1)))
    target=Counter();euler=Counter({wt:h[0][wt]-h[1][wt]for wt in h[0]})
    assert min(euler.values())>=0
    for (aa,bb),m in euler.items():
        num=s.expand(xx**(aa+2)*yy**(aa+2)*((xx**(aa+2)-xx**-(aa+2))*(yy**(bb+1)-yy**-(bb+1))-(yy**(aa+2)-yy**-(aa+2))*(xx**(bb+1)-xx**-(bb+1))))
        quotient,rem=s.div(s.Poly(num,xx,yy),s.Poly(den,xx,yy));assert rem==0
        for ex,co in quotient.terms():target[ex[0]-aa,ex[1]-aa]+=m*int(co)
    target=Counter({wt:n for wt,n in target.items()if n});assert sum(target.values())==38570 and min(target.values())>0
    b0,b1,b2=s.symbols('b0 b1 b2')
    chartQ=push(upper(s.Matrix([[b0,b1],[b1,b2]])),Qof(chartN,g0*x*x+g1*x*z+g2*z*z))
    variables=(a,b,d,e,b0,b1,b2,g0,g1,g2);R,*_=ring(variables,QQ)
    monomials=[Y[i]*Y[j]for i,j in combinations_with_replacement(range(4),2)]
    allpoly=[R.from_expr(s.Poly(chartQ[i,j],*Y).coeff_monomial(mon))for i,j in combinations(range(4),2)for mon in monomials]
    mons=sorted(set().union(*(set(f)for f in allpoly)))
    linear=s.Matrix([[f.get(ex,0)for f in allpoly]for ex in mons]);selected=list(linear.to_DM().rref()[1]);assert len(selected)==45
    polys=[allpoly[i]for i in selected]
    variable_weights=[(1,-1),(2,-2),(-2,0),(-3,1),(2,0),(1,1),(0,2),(-3,-1),(-2,-2),(-1,-3)]
    def weight(ex):return tuple(sum(c*w[j]for c,w in zip(ex,variable_weights))for j in range(2))
    coordinate_weights=[]
    for f in polys:
        ws={weight(ex)for ex in f};assert len(ws)==1;coordinate_weights.append(ws.pop())
    groups=defaultdict(list)
    for inds in combinations_with_replacement(range(45),4):groups[tuple(sum(coordinate_weights[i][k]for i in inds)for k in range(2))].append(inds)
    prime=32003;native='code/weighted_polynomial_evaluation_minors_20261101.cpp'
    with tempfile.TemporaryDirectory(prefix='ab-fourth-minors-')as temp:
        wd=Path(temp);inp=wd/'input.txt';out=wd/'output.json';binary=wd/'evaluate'
        with inp.open('w')as stream:
            stream.write(f'{prime} 1729 45 {max(target.values())} {len(target)}\n')
            for f in polys:
                stream.write(str(len(f))+'\n')
                for ex,co in f.items():
                    assert int(co.denominator)%prime
                    value=int(co.numerator)%prime*pow(int(co.denominator),-1,prime)%prime
                    stream.write(str(value)+' '+' '.join(map(str,ex))+'\n')
            for wt,r in sorted(target.items()):
                stream.write(f'{wt[0]} {wt[1]} {r} {len(groups[wt])}\n')
                for inds in groups[wt]:stream.write(' '.join(map(str,inds))+'\n')
        subprocess.run(['c++','-O3','-std=c++17','-I'+str(ROOT/'work/flint-headers/flint/3.5.0/include'),
                        '-I'+str(ROOT/'work/flint-headers/mpfr/4.2.2/include'),'-I/opt/homebrew/include',str(ROOT/native),
                        str(ROOT/'work/m2-runtime/lib/libflint.24.0.dylib'),'-L/opt/homebrew/lib','-lgmp','-o',str(binary)],check=True)
        env=os.environ.copy();env['DYLD_LIBRARY_PATH']=str(ROOT/'work/m2-runtime/lib')+':/opt/homebrew/lib'
        subprocess.run([str(binary),str(inp),str(out)],env=env,check=True)
        lower=json.loads(out.read_text())
    assert lower['total_rank']==38570 and all(r['determinant']for r in lower['groups'])
    paths=[str(Path(__file__).relative_to(ROOT)),native,'code/ab_origin_degree_four_backend_20261101.py',
           'research/notes/AB_INCIDENCE_20261101.md','research/notes/AB_ORIGIN_DEGREE_TWO_20261101.md',
           'research/notes/AB_ORIGIN_DEGREE_THREE_20261101.md']
    report=dict(all_passed=True,associated_graded_h0=41621,associated_graded_h1=3051,
                normalization_degree_four_dimension=38570,normalization_degree_four_H1=0,
                coordinate_degree_four_dimension=38570,Borel_Weil_Bott=table,
                H0_multiplicities={str(k):v for k,v in h[0].items()},H1_multiplicities={str(k):v for k,v in h[1].items()},
                P_map_constraints=constraints,variables=list(map(str,variables)),variable_weights=variable_weights,
                coordinate_indices=selected,coordinate_weights=coordinate_weights,
                coordinate_polynomials=[[[list(ex),str(co)]for ex,co in f.items()]for f in polys],
                evaluation_certificate=lower,seconds=time.time()-started,
                limitations=['Degree-four equality only; no all-degree normality or generation assertion.',
                             'P-cyclicity, evaluation and the filtration cohomology argument are essential proof dependencies.'],
                proof_note='research/notes/AB_ORIGIN_DEGREE_FOUR_20261101.md',
                input_sha256={p:hashlib.sha256((ROOT/p).read_bytes()).hexdigest()for p in paths})
    with args.output.open('x')as stream:json.dump(report,stream,indent=2);stream.write('\n')
    print('AB DEGREE FOUR GENERATION PASS',report['seconds'],flush=True)

if __name__=='__main__':main()
